-- Yogitech database schema (generated by: php yogi sql:build)
CREATE DATABASE IF NOT EXISTS `yogitech` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `yogitech`;

-- 001_create_users_table.sql
CREATE TABLE IF NOT EXISTS users (
    id                INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    role              ENUM('buyer','seller') NOT NULL DEFAULT 'buyer',
    name              VARCHAR(120) NOT NULL,
    email             VARCHAR(190) NOT NULL UNIQUE,
    password          VARCHAR(255) NOT NULL,
    phone             VARCHAR(20)  NULL,
    store_name        VARCHAR(120) NULL,
    store_description VARCHAR(500) NULL,
    address_line      VARCHAR(255) NULL,
    city              VARCHAR(100) NULL,
    province          VARCHAR(100) NULL,
    region            ENUM('NCR','Luzon','Visayas','Mindanao') NULL,
    postal_code       VARCHAR(10)  NULL,
    last_login_at     DATETIME NULL,
    created_at        DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at        DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    INDEX idx_users_role (role)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 002_create_categories_table.sql
CREATE TABLE IF NOT EXISTS categories (
    id          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    name        VARCHAR(80)  NOT NULL,
    slug        VARCHAR(80)  NOT NULL UNIQUE,
    api_slug    VARCHAR(80)  NULL COMMENT 'Matching DummyJSON category',
    icon        VARCHAR(30)  NOT NULL DEFAULT 'chip',
    description VARCHAR(255) NULL,
    sort_order  TINYINT UNSIGNED NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT IGNORE INTO categories (name, slug, api_slug, icon, description, sort_order) VALUES
 ('Smartphones', 'smartphones', 'smartphones',        'phone',  'Flagships, mid-rangers and budget phones', 1),
 ('Laptops',     'laptops',     'laptops',            'laptop', 'Ultrabooks, gaming rigs and workstations', 2),
 ('Tablets',     'tablets',     'tablets',            'tablet', 'Tablets for drawing, study and streaming', 3),
 ('Accessories', 'accessories', 'mobile-accessories', 'plug',   'Chargers, earbuds, cases, watches and more', 4);

-- 003_create_products_table.sql
CREATE TABLE IF NOT EXISTS products (
    id             INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    seller_id      INT UNSIGNED NOT NULL,
    category_id    INT UNSIGNED NOT NULL,
    external_id    INT UNSIGNED NULL COMMENT 'DummyJSON product id when imported',
    source         ENUM('manual','dummyjson') NOT NULL DEFAULT 'manual',
    sku            VARCHAR(60)  NULL,
    name           VARCHAR(180) NOT NULL,
    brand          VARCHAR(80)  NULL,
    description    TEXT NOT NULL,
    price          DECIMAL(12,2) NOT NULL COMMENT 'Selling price in PHP',
    compare_price  DECIMAL(12,2) NULL COMMENT 'Original price in PHP, shown struck through',
    api_price_usd  DECIMAL(10,2) NULL COMMENT 'Original USD price from the API',
    stock          INT UNSIGNED NOT NULL DEFAULT 0,
    thumbnail      VARCHAR(500) NULL,
    images         TEXT NULL COMMENT 'JSON array of image URLs',
    warranty       VARCHAR(120) NULL,
    return_policy  VARCHAR(120) NULL,
    specs          TEXT NULL COMMENT 'JSON object of extra specs',
    rating         DECIMAL(3,2) NOT NULL DEFAULT 0,
    rating_count   INT UNSIGNED NOT NULL DEFAULT 0,
    sold_count     INT UNSIGNED NOT NULL DEFAULT 0,
    status         ENUM('active','draft') NOT NULL DEFAULT 'active',
    created_at     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uq_products_seller_external (seller_id, external_id),
    INDEX idx_products_category (category_id),
    INDEX idx_products_status_price (status, price),
    CONSTRAINT fk_products_seller   FOREIGN KEY (seller_id)   REFERENCES users(id)      ON DELETE CASCADE,
    CONSTRAINT fk_products_category FOREIGN KEY (category_id) REFERENCES categories(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 004_create_cart_and_wishlist_tables.sql
CREATE TABLE IF NOT EXISTS cart_items (
    id         INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    user_id    INT UNSIGNED NOT NULL,
    product_id INT UNSIGNED NOT NULL,
    quantity   SMALLINT UNSIGNED NOT NULL DEFAULT 1,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uq_cart_user_product (user_id, product_id),
    CONSTRAINT fk_cart_user    FOREIGN KEY (user_id)    REFERENCES users(id)    ON DELETE CASCADE,
    CONSTRAINT fk_cart_product FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS wishlists (
    id         INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    user_id    INT UNSIGNED NOT NULL,
    product_id INT UNSIGNED NOT NULL,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uq_wishlist_user_product (user_id, product_id),
    CONSTRAINT fk_wishlist_user    FOREIGN KEY (user_id)    REFERENCES users(id)    ON DELETE CASCADE,
    CONSTRAINT fk_wishlist_product FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 005_create_vouchers_table.sql
CREATE TABLE IF NOT EXISTS vouchers (
    id           INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    code         VARCHAR(30) NOT NULL UNIQUE,
    description  VARCHAR(160) NOT NULL,
    type         ENUM('percent','fixed','shipping') NOT NULL,
    value        DECIMAL(10,2) NOT NULL,
    min_spend    DECIMAL(12,2) NOT NULL DEFAULT 0,
    max_discount DECIMAL(10,2) NULL,
    expires_at   DATETIME NULL,
    is_active    TINYINT(1) NOT NULL DEFAULT 1,
    created_at   DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT IGNORE INTO vouchers (code, description, type, value, min_spend, max_discount, expires_at) VALUES
 ('YOGI10',   '10% off, up to ₱1,000',                'percent',  10,  3000, 1000, NULL),
 ('CYBER500', '₱500 off orders ₱15,000 and up',        'fixed',    500, 15000, NULL, NULL),
 ('FREESHIP', 'Free shipping, up to ₱200',             'shipping', 200, 0,    NULL, NULL),
 ('NEON2077', '20% off, up to ₱3,000 (min ₱20,000)',   'percent',  20,  20000, 3000, NULL);

-- 006_create_orders_tables.sql
-- One checkout creates one order per seller (each ships separately).
CREATE TABLE IF NOT EXISTS orders (
    id                 INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    order_number       VARCHAR(30) NOT NULL UNIQUE,
    tracking_number    VARCHAR(30) NOT NULL UNIQUE,
    checkout_ref       VARCHAR(30) NOT NULL COMMENT 'Groups orders placed in one checkout',
    buyer_id           INT UNSIGNED NOT NULL,
    seller_id          INT UNSIGNED NOT NULL,
    status             ENUM('pending','confirmed','packed','shipped','in_transit','out_for_delivery','delivered','cancelled') NOT NULL DEFAULT 'pending',
    payment_method     ENUM('cod','gcash','card') NOT NULL DEFAULT 'cod',
    payment_status     ENUM('unpaid','paid','refunded') NOT NULL DEFAULT 'unpaid',
    subtotal           DECIMAL(12,2) NOT NULL,
    shipping_fee       DECIMAL(10,2) NOT NULL DEFAULT 0,
    discount           DECIMAL(10,2) NOT NULL DEFAULT 0,
    total              DECIMAL(12,2) NOT NULL,
    voucher_code       VARCHAR(30) NULL,
    recipient_name     VARCHAR(120) NOT NULL,
    phone              VARCHAR(20)  NOT NULL,
    address_line       VARCHAR(255) NOT NULL,
    city               VARCHAR(100) NOT NULL,
    province           VARCHAR(100) NOT NULL,
    region             ENUM('NCR','Luzon','Visayas','Mindanao') NOT NULL,
    postal_code        VARCHAR(10)  NULL,
    notes              VARCHAR(255) NULL,
    courier            VARCHAR(60)  NULL,
    estimated_from     DATE NULL,
    estimated_to       DATE NULL,
    shipped_at         DATETIME NULL,
    delivered_at       DATETIME NULL,
    cancelled_at       DATETIME NULL,
    cancel_reason      VARCHAR(255) NULL,
    created_at         DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at         DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    INDEX idx_orders_buyer (buyer_id, created_at),
    INDEX idx_orders_seller (seller_id, status),
    INDEX idx_orders_checkout (checkout_ref),
    CONSTRAINT fk_orders_buyer  FOREIGN KEY (buyer_id)  REFERENCES users(id) ON DELETE CASCADE,
    CONSTRAINT fk_orders_seller FOREIGN KEY (seller_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS order_items (
    id           INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    order_id     INT UNSIGNED NOT NULL,
    product_id   INT UNSIGNED NULL,
    product_name VARCHAR(180) NOT NULL COMMENT 'Snapshot at time of purchase',
    thumbnail    VARCHAR(500) NULL,
    unit_price   DECIMAL(12,2) NOT NULL,
    quantity     SMALLINT UNSIGNED NOT NULL,
    line_total   DECIMAL(12,2) NOT NULL,
    CONSTRAINT fk_items_order   FOREIGN KEY (order_id)   REFERENCES orders(id)   ON DELETE CASCADE,
    CONSTRAINT fk_items_product FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Every status change becomes a timeline entry on the tracking page.
CREATE TABLE IF NOT EXISTS shipment_events (
    id          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    order_id    INT UNSIGNED NOT NULL,
    status      VARCHAR(30)  NOT NULL,
    title       VARCHAR(120) NOT NULL,
    description VARCHAR(255) NULL,
    location    VARCHAR(120) NULL,
    created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    INDEX idx_events_order (order_id, created_at),
    CONSTRAINT fk_events_order FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 007_create_reviews_table.sql
CREATE TABLE IF NOT EXISTS reviews (
    id            INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    product_id    INT UNSIGNED NOT NULL,
    user_id       INT UNSIGNED NULL COMMENT 'NULL for reviews imported from the API',
    order_id      INT UNSIGNED NULL,
    reviewer_name VARCHAR(120) NOT NULL,
    rating        TINYINT UNSIGNED NOT NULL,
    comment       VARCHAR(1000) NOT NULL,
    created_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uq_review_user_product (user_id, product_id),
    INDEX idx_reviews_product (product_id),
    CONSTRAINT fk_reviews_product FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE,
    CONSTRAINT fk_reviews_user    FOREIGN KEY (user_id)    REFERENCES users(id)    ON DELETE SET NULL,
    CONSTRAINT fk_reviews_order   FOREIGN KEY (order_id)   REFERENCES orders(id)   ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 008_create_email_logs_table.sql
-- Every notification email (sent, failed or only logged) is recorded here.
CREATE TABLE IF NOT EXISTS email_logs (
    id         INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    user_id    INT UNSIGNED NULL,
    order_id   INT UNSIGNED NULL,
    to_email   VARCHAR(190) NOT NULL,
    subject    VARCHAR(255) NOT NULL,
    type       VARCHAR(40)  NOT NULL,
    driver     VARCHAR(20)  NOT NULL,
    status     ENUM('sent','failed','logged') NOT NULL,
    error      VARCHAR(500) NULL,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    INDEX idx_email_logs_user (user_id),
    INDEX idx_email_logs_order (order_id),
    CONSTRAINT fk_email_logs_user  FOREIGN KEY (user_id)  REFERENCES users(id)  ON DELETE SET NULL,
    CONSTRAINT fk_email_logs_order FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 009_create_password_resets_table.sql
-- Forgot password: one-time reset tokens (only the SHA-256 hash is stored).
-- auth_version is bumped on every password change/reset to sign out other sessions.
ALTER TABLE users ADD COLUMN auth_version INT UNSIGNED NOT NULL DEFAULT 1 AFTER password;

CREATE TABLE IF NOT EXISTS password_resets (
    id          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    user_id     INT UNSIGNED NOT NULL,
    token_hash  CHAR(64) NOT NULL UNIQUE,
    expires_at  DATETIME NOT NULL,
    used_at     DATETIME NULL,
    ip          VARCHAR(45) NULL,
    created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    INDEX idx_password_resets_user (user_id, created_at),
    CONSTRAINT fk_password_resets_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 010_add_voucher_limits.sql
-- Voucher usage limits. NULL = unlimited.
ALTER TABLE vouchers
    ADD COLUMN usage_limit    INT UNSIGNED NULL AFTER max_discount,
    ADD COLUMN per_user_limit INT UNSIGNED NULL AFTER usage_limit;

-- One row per checkout that used a voucher. released_at is set when every order of
-- that checkout is cancelled, which gives the use back.
CREATE TABLE IF NOT EXISTS voucher_redemptions (
    id           INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    voucher_id   INT UNSIGNED NOT NULL,
    user_id      INT UNSIGNED NOT NULL,
    checkout_ref VARCHAR(30)  NOT NULL UNIQUE,
    discount     DECIMAL(10,2) NOT NULL DEFAULT 0,
    released_at  DATETIME NULL,
    created_at   DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    INDEX idx_redemptions_voucher (voucher_id, released_at),
    INDEX idx_redemptions_user (user_id, voucher_id, released_at),
    CONSTRAINT fk_redemptions_voucher FOREIGN KEY (voucher_id) REFERENCES vouchers(id) ON DELETE CASCADE,
    CONSTRAINT fk_redemptions_user    FOREIGN KEY (user_id)    REFERENCES users(id)    ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

UPDATE vouchers SET usage_limit = 1000, per_user_limit = 3 WHERE code = 'YOGI10';
UPDATE vouchers SET usage_limit = 200,  per_user_limit = 1 WHERE code = 'CYBER500';
UPDATE vouchers SET usage_limit = NULL, per_user_limit = 5 WHERE code = 'FREESHIP';
UPDATE vouchers SET usage_limit = 100,  per_user_limit = 1 WHERE code = 'NEON2077';

-- Count vouchers already used in existing orders.
INSERT IGNORE INTO voucher_redemptions (voucher_id, user_id, checkout_ref, discount, released_at, created_at)
SELECT v.id, o.buyer_id, o.checkout_ref, SUM(o.discount),
       CASE WHEN SUM(o.status <> 'cancelled') = 0 THEN MAX(o.cancelled_at) ELSE NULL END,
       MIN(o.created_at)
  FROM orders o JOIN vouchers v ON v.code = o.voucher_code
 WHERE o.voucher_code IS NOT NULL
 GROUP BY v.id, o.buyer_id, o.checkout_ref;

-- 011_mask_names_in_tracking.sql
-- Tracking timelines are public: stop showing the recipient's full name.
UPDATE shipment_events SET description = 'Parcel delivered to the recipient.'
 WHERE status = 'delivered' AND description LIKE 'Parcel received by %';

-- 012_create_payments_table.sql
-- Online payments (GCash, card). One row per payment attempt for a checkout.
-- status: pending → authorized (approved on the gateway page) → paid (orders updated).
-- gateway: sandbox (built-in GCash/card simulator) or paymongo (PayMongo test mode).
CREATE TABLE IF NOT EXISTS payments (
    id            INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    public_id     CHAR(24) NOT NULL UNIQUE,
    checkout_ref  VARCHAR(30) NOT NULL,
    buyer_id      INT UNSIGNED NOT NULL,
    gateway       VARCHAR(20) NOT NULL,
    method        ENUM('gcash','card') NOT NULL,
    amount        DECIMAL(12,2) NOT NULL,
    status        ENUM('pending','authorized','paid','failed','cancelled') NOT NULL DEFAULT 'pending',
    gateway_ref   VARCHAR(120) NULL,
    payer         VARCHAR(60) NULL,
    failure       VARCHAR(255) NULL,
    created_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    paid_at       DATETIME NULL,
    INDEX idx_payments_checkout (checkout_ref, status),
    CONSTRAINT fk_payments_buyer FOREIGN KEY (buyer_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 013_add_product_videos.sql
-- Optional product video (YouTube link or an uploaded .mp4/.webm), shown before the photos.
ALTER TABLE products ADD COLUMN video_url VARCHAR(500) NULL AFTER images;

